def graphOffset {n : ℕ} (h : FinitePoint n → ℂ × ℂ) (b : Bool)
    (z : Variables n → ℂ) : ℂ :=
  z (Sum.inr b) - if b then (h (sourceCoordinates z)).2 else (h (sourceCoordinates z)).1

