theorem continuousOn_graphOffset {n : ℕ} {R : ℝ}
    (h : FinitePoint n → ℂ × ℂ) {S : Set (Variables n → ℂ)}
    (hbase : ∀ z ∈ S, sourceCoordinates z ∈ polydisc n R)
    (hh : ContinuousOn h (polydisc n R)) (b : Bool) :
    ContinuousOn (graphOffset h b) S
